    public enum GeometryKey
    {
        SandParticle,
        UnroundedRock,
        RoundedRock,
        RoundedRock2,
        Granite,
        Prs,
        Torf,
        Clay,
        Gneis,
    }

    public record GeometryDefinition(string Markup, int Width, int Height, bool Filled);

    public record HatchConfig(
        IReadOnlyList<HatchElement> Elements,
        System.Drawing.Color? Color = null,
        System.Drawing.Color? BackgroundColor = null,
        double MaxClippedFraction = 0.5);

    public record HatchElement(
        GeometryKey Geometry,
        int StepX,
        int StepY,
        bool RandomOffset = false,
        double Scale = 1.0,
        int PlacementAttempts = 8,
        bool RandomRotation = false,
        bool IngnoreInrersections = false);

