    public static class HatchImageRenderer
    {
        public static byte[] Render(
            int width,
            int height,
            IReadOnlyList<HatchElement> elements,
            System.Drawing.Color? color = null,
            double maxClippedFraction = 0.5)
        {
            width = Math.Max(1, width);
            height = Math.Max(1, height);

            maxClippedFraction = Math.Clamp(
                maxClippedFraction,
                0.0,
                1.0);

            var visual = new DrawingVisual();

            // Уже занятые области.
            var occupied = new List<Rect>();

            using (var dc = visual.RenderOpen())
            {
                foreach (var element in elements)
                {
                    if (!GeometriesData.Geometries.TryGetValue(
                            element.Geometry,
                            out var definition))
                    {
                        continue;
                    }

                    var geometry = Geometry.Parse(definition.Markup);

                    // Центр геометрии В ИСХОДНЫХ (не масштабированных,
                    // не смещённых) координатах — именно в этой системе
                    // координат работает поворот при отрисовке, т.к.
                    // Rotate применяется к геометрии ПЕРВЫМ (см. ниже).
                    var rawBounds = geometry.Bounds;
                    var rawCenterX = rawBounds.X + rawBounds.Width / 2.0;
                    var rawCenterY = rawBounds.Y + rawBounds.Height / 2.0;

                    // Смещение, которое центрирует фигуру внутри её ячейки
                    // StepX×StepY. Раньше фигура рисовалась так, как она
                    // задана в собственных координатах пути — если путь
                    // начинается почти от y=0 и невысокий (как у Gneis,
                    // ширина ~22×высота ~5), а StepY большой (40), фигура
                    // оказывалась прижатой к верхнему краю своей полосы,
                    // а не по центру. Здесь считаем неповёрнутый bounding
                    // box фигуры в позиции (0,0) и выравниваем его центр
                    // по центру ячейки — но ТОЛЬКО по той оси, где фигура
                    // реально помещается в ячейку. Если по какой-то оси
                    // фигура шире/выше своего шага (как тот же Gneis с
                    // Scale=1.4 при StepX=15 — это сделано специально,
                    // чтобы соседние зигзаги перекрывались и образовывали
                    // непрерывную линию), центрирование по этой оси
                    // применять нельзя: оно будет расталкивать фигуры к
                    // краям изображения и они начнут вылезать за границы.
                    // В этом случае ось просто остаётся выровненной по
                    // сетке, как раньше.
                    var unrotatedBounds = GetGeometryBounds(
                        geometry,
                        element.Scale,
                        0,
                        0,
                        0);

                    double baseOffsetX = unrotatedBounds.Width <= element.StepX
                        ? element.StepX / 2.0
                            - (unrotatedBounds.X + unrotatedBounds.Width / 2.0)
                        : 0;

                    double baseOffsetY = unrotatedBounds.Height <= element.StepY
                        ? element.StepY / 2.0
                            - (unrotatedBounds.Y + unrotatedBounds.Height / 2.0)
                        : 0;

                    var drawColor = color.HasValue
                        ? Color.FromArgb(
                            color.Value.A,
                            color.Value.R,
                            color.Value.G,
                            color.Value.B)
                        : Colors.Black;

                    var brush = new SolidColorBrush(drawColor);
                    var pen = new Pen(brush, 1);

                    // Собираем все узлы сетки заранее и перемешиваем
                    // порядок их обработки. Без этого сканирование всегда
                    // идёт строго слева-направо/сверху-вниз, и по мере
                    // заполнения occupied более поздние (правые/нижние)
                    // клетки систематически проигрывают конкуренцию за
                    // место, что и даёт неравномерную, "перекошенную"
                    // плотность узора.
                    var cells = new List<(int X, int Y)>();
                    for (int y = 0; y < height; y += element.StepY)
                    {
                        for (int x = 0; x < width; x += element.StepX)
                        {
                            cells.Add((x, y));
                        }
                    }

                    // Fisher–Yates shuffle.
                    for (int i = cells.Count - 1; i > 0; i--)
                    {
                        int j = Random.Shared.Next(i + 1);
                        (cells[i], cells[j]) = (cells[j], cells[i]);
                    }

                    foreach (var (x, y) in cells)
                    {
                        int attempts = element.RandomOffset
                            ? Math.Max(1, element.PlacementAttempts)
                            : 1;

                        for (int attempt = 0; attempt < attempts; attempt++)
                        {
                            // База — центр ячейки, а не её левый верхний
                            // угол. Без RandomOffset фигура ставится ровно
                            // по центру ячейки детерминированно.
                            int offsetX = (int)Math.Round(baseOffsetX);
                            int offsetY = (int)Math.Round(baseOffsetY);

                            if (element.RandomOffset)
                            {
                                // Джиттер теперь колеблется вокруг уже
                                // центрированной позиции (а не вокруг угла
                                // ячейки), поэтому диапазон уменьшен —
                                // иначе на маленьких StepX/StepY фигуру
                                // снова могло бы вынести к краю.
                                offsetX += Random.Shared.Next(
                                    -element.StepX / 4,
                                    element.StepX / 4 + 1);

                                offsetY += Random.Shared.Next(
                                    -element.StepY / 4,
                                    element.StepY / 4 + 1);
                            }

                            double rotation = element.RandomRotation
                                ? Random.Shared.NextDouble() * 360.0
                                : 0.0;

                            Rect bounds = GetGeometryBounds(
                                geometry,
                                element.Scale,
                                x + offsetX,
                                y + offsetY,
                                rotation);

                            // 1. Проверяем, насколько элемент выходит
                            // за пределы изображения.
                            if (GetClippedFraction(
                                    bounds,
                                    width,
                                    height) > maxClippedFraction)
                            {
                                continue;
                            }

                            // 2. Проверяем пересечение с уже размещёнными.
                            if (IntersectsOccupied(bounds, occupied) && !element.IngnoreInrersections)
                                continue;

                            // 3. Можно рисовать.

                            dc.PushTransform(
                                new TranslateTransform(
                                    x + offsetX,
                                    y + offsetY));

                            if (element.Scale != 1.0)
                            {
                                dc.PushTransform(
                                    new ScaleTransform(
                                        element.Scale,
                                        element.Scale));
                            }

                            if (element.RandomRotation)
                            {
                                // Поворот выполняется ПЕРВЫМ (он ближе всего
                                // к геометрии в стеке PushTransform), поэтому
                                // центр поворота должен задаваться в исходных
                                // координатах геометрии (rawCenterX/Y), а НЕ
                                // в мировых координатах bounds — раньше здесь
                                // использовался bounds.X/Y, что уже включало
                                // смещение x+offsetX и приводило к повороту
                                // вокруг неверной точки. Из-за этого реально
                                // отрисованная фигура не совпадала с
                                // прямоугольником, зарезервированным в
                                // occupied, и в узоре появлялись то скрытые
                                // наложения, то пустые проплешины.
                                dc.PushTransform(
                                    new RotateTransform(
                                        rotation,
                                        rawCenterX,
                                        rawCenterY));
                            }

                            dc.DrawGeometry(
                                definition.Filled ? brush : null,
                                definition.Filled ? null : pen,
                                geometry);

                            if (element.RandomRotation)
                                dc.Pop();

                            if (element.Scale != 1.0)
                                dc.Pop();

                            dc.Pop();

                            occupied.Add(bounds);

                            break;
                        }

                        // Не удалось найти свободное место —
                        // просто пропускаем элемент.
                    }
                }
            }

            var bitmap = new RenderTargetBitmap(
                width,
                height,
                96,
                96,
                PixelFormats.Pbgra32);

            bitmap.Render(visual);

            var encoder = new PngBitmapEncoder();
            encoder.Frames.Add(BitmapFrame.Create(bitmap));

            using var stream = new MemoryStream();
            encoder.Save(stream);

            return stream.ToArray();
        }

        private static Rect GetGeometryBounds(
            Geometry geometry,
            double scale,
            double x,
            double y,
            double rotation = 0)
        {
            // ВАЖНО: порядок применения трансформаций должен зеркалить
            // порядок PushTransform при отрисовке (Translate -> Scale ->
            // Rotate добавляются в стек в этом порядке, но т.к. каждый
            // следующий PushTransform оборачивает предыдущий, к самой
            // геометрии первым применяется Rotate, затем Scale, и только
            // затем Translate). Раньше здесь сначала применялся Scale,
            // а потом Rotate вокруг НЕмасштабированного центра — обратный
            // и несогласованный с отрисовкой порядок, из-за чего
            // вычисленный прямоугольник не совпадал с реально
            // нарисованной фигурой.
            var bounds = geometry.Bounds;

            Rect current = bounds;

            if (rotation != 0)
            {
                var centerX = bounds.X + bounds.Width / 2.0;
                var centerY = bounds.Y + bounds.Height / 2.0;

                var rotate = new RotateTransform(
                    rotation,
                    centerX,
                    centerY);

                current = rotate.TransformBounds(current);
            }

            if (scale != 1.0)
            {
                var scaleTransform = new ScaleTransform(scale, scale);
                current = scaleTransform.TransformBounds(current);
            }

            return new Rect(
                x + current.X,
                y + current.Y,
                current.Width,
                current.Height);
        }

        private static double GetClippedFraction(
            Rect bounds,
            int width,
            int height)
        {
            if (bounds.Width <= 0 || bounds.Height <= 0)
                return 1.0;

            var canvas = new Rect(
                0,
                0,
                width,
                height);

            var visible = Rect.Intersect(
                bounds,
                canvas);

            if (visible.IsEmpty)
                return 1.0;

            double totalArea =
                bounds.Width *
                bounds.Height;

            double visibleArea =
                visible.Width *
                visible.Height;

            return 1.0 - visibleArea / totalArea;
        }

        private static bool IntersectsOccupied(
            Rect candidate,
            List<Rect> occupied)
        {
            foreach (var existing in occupied)
            {
                if (candidate.IntersectsWith(existing))
                    return true;
            }

            return false;
        }
    }
}